return 12.;
return mth;
}
if (t > 0) {
int prev_mth = xint(pol_month(t-1));
if (prev_mth == 12)
return 1.0;
return prev_mth +1.0;
}
int next_mth = xint(pol_month(t+1));
if (next_mth == 1)
return 12.0;
return next_mth - 1.0;

