void set_work_variables(){
if (main->run_name==EPIFP)
policy_pup_status_w="Y";
sl_type=LIFE;
if ((main->other_eski_first==Y)&&(flag_lapse==2))
policy_pup_status_w="Y";
int i;
int lookup_index;
// adjust sheckel values from data to madad
prem_curr_w = prem_curr * madad_current / 100.;
prem_orig_curr_w = prem_orig_curr * madad_current / 100.;
sum_insured_curr_w = sum_insured_curr * madad_current / 100.;
policy_fee_curr_w = policy_fee_curr * madad_current / 100.;
bonus_exst_w = bonus_exst * madad_current / 100.;
reserve_exst_w = reserve_exst * madad_current / 100.;
fefrman_extra_reserve_w = fefrman_extra_reserve * madad_current / 100.;
// add modal loading to premium and policy fee (discounts and u/w loading will then be applied to
this too)
prem_curr_w = prem_curr_w * (1. + modal_loading);
policy_fee_curr_w = policy_fee_curr_w * (1. + modal_loading);
prem_orig_curr_w = prem_orig_curr_w * (1. + modal_loading);
prem_curr_waiver_trad = prem_curr_w * (1+underwriting_load);
// dac variables
//
dac_book_inforce_w = dac_book_inforce * madad_current / 100.;
//dac_tax_inforce_w = dac_tax_inforce * madad_current / 100.;
// ****** Calculate commencement and maturity periods *************************
// commence_period_w is that value of t at which the policy starts.
// For example, if the policy commenced 12 months prior to the valuation
// date then commence_period_w = -12.
// A policy starting 6 months after the valuation date (future new business)
// will have commence_period_w = 6, since it's elapsed months is negative.
commence_period_w = -elapsed_months;
// Sometimes reference needs to be made to the valuation date for an in-force
// policy or to the policy commencement for a future new business policy. This
// is achieved by using commence_nonneg_w.
commence_nonneg_w = max(0, commence_period_w);
// maturity_period_w is that value of t at which the policy ends.
// A LTC policy can have a claim period that continues past the policy (coverage) period, in which
// case maturity_period_w will be the period when the claims end, and maturity_period_w_coverage_w
// will be the earlier period when the coverage end (based on benefit_term).
// Premiums end according to the premium_term variable.
if ((ben_class=="GIMLA_A")||(ben_class=="GIMLA_B")||(ben_class=="GIMLA_G")||(ben_class=="GIMLA_H"))
{
benefit_term_w = 1440-age_exact_issue*12;
//benefit_term_w=elapsed_months+720;
//if (sex == "M")
//benefit_term_w = max(elapsed_months + 12 , 12 * (gil_retirement_m - age_exact_issue));
//else  benefit_term_w = max(elapsed_months + 12 , 12 * (gil_retirement_f - age_exact_issue));
}
else
{
if (policy_pup_status_w == "T") benefit_term_w = benefit_term + contin_period;
else
benefit_term_w = benefit_term;
}
maturity_period_w = benefit_term_w - elapsed_months;
if ((flag_annuity==1)&&(main->other_demografi=="Y")) maturity_period_w = main->num_cf_movement/2;
// Store original maturity period - before it gets adjusted for assumed retirement age
maturity_period_orig = benefit_term - elapsed_months;
if ((flag_annuity==1)&&(main->other_demografi=="Y")) maturity_period_orig = main->num_cf_movement/2;
if (main->other_demografi==Y)
{
if (flag_death==1) maturity_period_w=int(main->num_cf_movement/2);
}
if (main->other_eski_first==Y)
{
if (flag_lapse==1) maturity_period_w=int(main->num_cf_movement/2);
}
// Calculate variable matan_period
matan_period = commence_period_w + matan_term;
//set surrender values rates,
// until original maturity age, read from table, af
for (i=xint(elapsed_months/12.); i <= xint(benefit_term/12.); i++)
{
temp_cl_i = i;
sv_rate_array_w[i] = sv_rates;
}
// after original maturity age, increase with interest
for (i=xint(benefit_term/12.)+1; i <= xint(benefit_term_w/12.)+1; i++)
sv_rate_array_w[i] = sv_rate_array_w[i-1] * (1+interest_rate_res);
//set paid up values rates
//for (i=xint(elapsed_months/12.); i <= xint(benefit_term_w/12.); i++)
for (i=xint(elapsed_months/12.); i <= xint(benefit_term/12.); i++)
{
temp_cl_i = i;
pup_rate_array_w[i] = pup_rates;
/* earlier pup_rate_array_w[i] = pup_rates_tbl(index_pup_rates, i+2);
Taken i instead of i+2. Earlier code was looking at i+2 th column which is
ith header. */
}
for (i=xint(benefit_term/12.)+1; i <= xint(benefit_term_w/12.)+1; i++)
pup_rate_array_w[i] = pup_rate_array_w[i-1];
// set reinsurance premium rates
for (i=xint(age_exact_issue); i <= 119; i++) // assumes that reinsurance premium table has rates to
age 119
// change to x+2  - inbal 12/12/2010 the last formula was x+3
{
temp_cl_i = i;
prem_rate_rein_array_w[i] = premium_rates_rein;
prem_rate_rein_array_w[120] = prem_rate_rein_array_w[119];
}
int end_loop = GetColumnKeyValuesCount(lapse_rate_tbl);
for (i=1; i <= end_loop; i++)
{
temp_cl_i = i;
lapse_rate_array_w[i] = lapse_rate_tbl;
}
for (i=end_loop+1; i <= benefit_term_w/12 + 1; i++)
lapse_rate_array_w[i] = lapse_rate_array_w[end_loop] ;
if (policy_pup_status_w =="N" && ! inlist(lapse_set,"TERM,PHI,LTC,HEALTH,MORTGAGE,CI,TOP_FINAN")){
int end_loop_pp = GetColumnKeyValuesCount(lapse_rate_tbl);
for (i=1; i <= end_loop_pp; i++)
{
temp_cl_i = i;
lapse_rate_array_w_pup_prop[i] = lapse_rate_pup_prop_tbl;
lapse_rate_array_w_pup_prop_prm[i] = lapse_rate_tbl_prm;
}
